    job_id: String(job.id || job.slug || ''),
    job_title: (job.position || '').trim(),
    company: (job.company || '').trim(),
    job_url: job.url || '',
    source: 'Remote OK',
    location_text: job.location || 'Worldwide',
    salary: job.salary || '',
    description: (job.description || '').substring(0, 5000),
    posted_date: job.date || new Date().toISOString(),
    tags: Array.isArray(job.tags) ? job.tags.join(', ') : ''
  }
}));

const raw = $input.first().json;
const jobs = raw.jobs || [];
return jobs.map(job => ({
  json: {
    job_id: String(job.id || ''),
    job_title: (job.title || '').trim(),
    company: (job.company_name || '').trim(),
    job_url: job.url || '',
    source: 'Remotive',
    location_text: job.candidate_required_location || 'Worldwide',
    salary: job.salary || '',
    description: (job.description || '').substring(0, 5000),
    posted_date: job.publication_date || new Date().toISOString(),
    tags: Array.isArray(job.tags) ? job.tags.join(', ') : (job.job_type || '')
  }
}));

const xml = $input.first().json.data || '';
const items = [];
const itemMatches = xml.match(/<item>[\s\S]*?<\/item>/g) || [];
for (const block of itemMatches) {
  const get = (tag) => {
    const m = block.match(new RegExp('<' + tag + '(?:[^>]*)><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/' + tag + '>|<' + tag + '(?:[^>]*)>([\\s\\S]*?)<\/' + tag + '>'));
    return m ? (m[1] || m[2] || '').trim() : '';
  };
  const url = get('link') || get('guid');
  const title = get('title');
  const company = get('author') || (title.includes(':') ? title.split(':')[0].trim() : '');
  items.push({
    json: {
      job_id: url,
      job_title: title.includes(':') ? title.split(':').slice(1).join(':').trim() : title,
      company: company,
      job_url: url,
      source: 'We Work Remotely',
      location_text: get('region') || 'Worldwide',
      salary: '',
      description: get('description').replace(/<[^>]+>/g, ' ').substring(0, 5000),
      posted_date: get('pubDate') || new Date().toISOString(),
      tags: get('category') || ''
    }
  });
}
return items;

const raw = $input.first().json;
