// Wellfound requires authentication for full job data.
// This extracts what's publicly available.
const html = $input.first().json.data || '';
const items = [];
// Extract JSON-LD structured data if present
const ldMatches = html.match(/<script type="application\/ld\+json">[\s\S]*?<\/script>/g) || [];
for (const block of ldMatches) {
  try {
    const json = JSON.parse(block.replace(/<script[^>]*>/,'').replace(/<\/script>/,'').trim());
    if (json['@type'] === 'JobPosting') {
      items.push({
        json: {
          job_id: json.url || '',
          job_title: json.title || '',
          company: json.hiringOrganization?.name || '',
          job_url: json.url || '',
          source: 'Wellfound',
          location_text: json.jobLocation?.address?.addressLocality || 'Remote',
          salary: json.baseSalary ? `${json.baseSalary.value?.minValue}-${json.baseSalary.value?.maxValue} ${json.baseSalary.currency}` : '',
          description: (json.description || '').replace(/<[^>]+>/g,'').substring(0, 5000),
          posted_date: json.datePosted || new Date().toISOString(),
          tags: ''
        }
      });
    }
  } catch(e) {}
}
return items.length > 0 ? items : [{ json: { _empty: true, source: 'Wellfound', _note: 'No structured data found - Wellfound may require auth' } }];

const html = $input.first().json.data || '';
const items = [];
// Try JSON-LD first
const ldMatches = html.match(/<script type="application\/ld\+json">[\s\S]*?<\/script>/g) || [];
for (const block of ldMatches) {
  try {
    const json = JSON.parse(block.replace(/<script[^>]*>/,'').replace(/<\/script>/,'').trim());
    const postings = Array.isArray(json) ? json : [json];
    for (const posting of postings) {
      if (posting['@type'] === 'JobPosting') {
        items.push({
          json: {
            job_id: posting.url || '',
            job_title: posting.title || '',
            company: posting.hiringOrganization?.name || '',
            job_url: posting.url || '',
            source: 'YC Work at Startup',
            location_text: 'Remote',
            salary: '',
            description: (posting.description || '').replace(/<[^>]+>/g,'').substring(0, 5000),
            posted_date: posting.datePosted || new Date().toISOString(),
            tags: 'YC startup'
          }
        });
      }
    }
  } catch(e) {}
}
return items.length > 0 ? items : [{ json: { _empty: true, source: 'YC Work at Startup' } }];

const response = $input.first().json;
const jobs = response.jobs || response.results || [];
if (Array.isArray(jobs) && jobs.length > 0) {
  return jobs.map(job => ({
    json: {
      job_id: String(job.id || job.externalId || ''),
      job_title: (job.title || '').trim(),
      company: (job.company?.name || '').trim(),
      job_url: `https://app.otta.com/jobs/${job.id}`,
      source: 'Otta',
      location_text: job.locationStr || 'Remote',
      salary: job.salary ? `${job.salary.min || ''}-${job.salary.max || ''} ${job.salary.currency || 'USD'}` : '',
      description: (job.description || '').substring(0, 5000),
      posted_date: job.publishedAt || new Date().toISOString(),
      tags: (job.skills || []).join(', ')
    }
  }));
}
return [{ json: { _empty: true, source: 'Otta' } }];

const items = $input.all();
const today = new Date().toISOString().split('T')[0];

return items
  .filter(item => !item.json._empty)
  .map(item => {
    const j = item.json;
    const raw_url = (j.job_url || '').trim();
    const job_id = j.job_id || raw_url || `${j.company}-${j.job_title}`.replace(/\s+/g, '-').toLowerCase().substring(0, 80);
    return {
      json: {
        date_found: today,
        job_id: job_id,
        job_title: (j.job_title || '').trim().substring(0, 200),
        company: (j.company || '').trim().substring(0, 100),
        job_url: raw_url,
        source: j.source || 'Unknown',
        location_text: (j.location_text || '').trim().substring(0, 200),
        salary: (j.salary || '').trim().substring(0, 100),
        description: (j.description || '').trim().substring(0, 5000),
        posted_date: j.posted_date || today,
        tags: (j.tags || '').trim().substring(0, 300)
      }
    };
  })
  .filter(item => item.json.job_title && item.json.job_url);

const items = $input.all();

// Get existing jobs from Google Sheets node
let existingUrls = new Set();
let existingKeys = new Set();
try {
  const existing = $('Read Existing Jobs').all();
  for (const e of existing) {
    if (e.json.job_url) existingUrls.add(e.json.job_url.trim());
    if (e.json.company && e.json.job_title) {
      existingKeys.add(`${e.json.company}|${e.json.job_title}`.toLowerCase());
    }
  }
} catch(err) {
  // First run - no existing data
}

const seenUrls = new Set(existingUrls);
const seenKeys = new Set(existingKeys);
const unique = [];

for (const item of items) {
  const url = (item.json.job_url || '').trim();
  const key = `${item.json.company}|${item.json.job_title}`.toLowerCase();

  if (!seenUrls.has(url) && !seenKeys.has(key)) {
    seenUrls.add(url);
    seenKeys.add(key);
    unique.push(item);
  }
}

return unique;

const items = $input.all();

const REJECT = [
  /\bus only\b/i, /\busa only\b/i, /\bunited states only\b/i,
  /\bcanada only\b/i, /\buk only\b/i, /\beu only\b/i,
  /\beurope only\b/i, /\baustralia only\b/i,
  /must be based in/i, /must live in/i, /must reside in/i,
  /must be located in/i, /must be authorized to work in/i,
  /local work permit required/i, /right to work in/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i, /office required/i,
  /in-office/i, /remote within.*only/i, /only within/i,
  /fixed us hours/i, /fixed eu hours/i, /us timezone required/i,
  /must work.*eastern time/i, /must work.*pacific time/i,
  /no international/i, /domestic only/i
];

const passed = [];
const rejected = [];

for (const item of items) {
  const text = `${item.json.description} ${item.json.location_text} ${item.json.tags}`.toLowerCase();
  let rejectedBy = null;
  for (const pattern of REJECT) {
    if (pattern.test(text)) {
      rejectedBy = pattern.source;
      break;
    }
  }
  if (rejectedBy) {
    item.json._rejected_reason = `Hard filter: ${rejectedBy}`;
    rejected.push(item);
  } else {
    passed.push(item);
  }
}

// Store rejected for later use (we handle via separate output routing)
// Return only passed items
return passed;

