const items = $input.all();
return items.map(item => {
  let aiResult = {};
  try {
    const content = item.json.message?.content ||
      item.json.choices?.[0]?.message?.content ||
      item.json.content ||
      '{}';
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) aiResult = JSON.parse(jsonMatch[0]);
  } catch(e) {
    aiResult = {
      taiwan_eligible: 'unclear',
      reason: 'AI parse error - needs manual check',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check'
    };
  }

  return {
    json: {
      ...item.json,
      taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
      taiwan_reason: aiResult.reason || '',
      location_risk: aiResult.location_risk || 'medium',
      timezone_risk: aiResult.timezone_risk || 'medium',
      contractor_possible: aiResult.contractor_possible || 'unclear',
      ai_decision: aiResult.decision || 'manual_check'
    }
  };
});

const items = $input.all();

const ASYNC_REJECT = [
  /strict 9.?to.?5/i, /fixed (us|est|pst|cet|gmt) hours/i,
  /daily live calls required/i,
  /must overlap full business day/i,
  /real.?time collaboration required/i,
  /must be online.*9am.*(est|pst|cet)/i
];

const ASYNC_HIGH = [
  /\basync\b/i, /\basync-first\b/i, /\basynchronous\b/i,
  /low meeting culture/i, /no meeting/i, /written.?first/i
];

const ASYNC_MEDIUM = [
  /flexible hours/i, /flexible schedule/i,
  /work across time zones/i, /global team/i,
  /distributed team/i
];

const ASYNC_LOW = [
  /remote.?first/i, /\bremote\b/i
];

return items.map(item => {
  const text = `${item.json.description} ${item.json.tags}`;

  for (const p of ASYNC_REJECT) {
    if (p.test(text)) {
      item.json.async_level = 'sync_required';
      item.json._async_rejected = true;
      return { json: item.json };
    }
  }

  let asyncLevel = 'unknown';
  if (ASYNC_HIGH.some(p => p.test(text))) asyncLevel = 'high';
  else if (ASYNC_MEDIUM.some(p => p.test(text))) asyncLevel = 'medium';
  else if (ASYNC_LOW.some(p => p.test(text))) asyncLevel = 'low';

  return { json: { ...item.json, async_level: asyncLevel } };
}).filter(item => !item.json._async_rejected);

const items = $input.all();

const ROLE_HIGH = [
  /data analyst/i, /data scientist/i, /\bBI analyst\b/i,
  /business intelligence/i, /marketing analyst/i,
  /performance marketing analyst/i, /growth analyst/i,
  /ai marketing/i, /ai automation/i, /ai workflow/i,
  /martech analyst/i, /marketing data/i
];

const ROLE_MEDIUM = [
  /analytics engineer/i, /product analyst/i,
  /digital marketing/i, /growth hacker/i,
  /paid media/i, /campaign analyst/i,
  /crm analyst/i, /seo analyst/i
];

return items.map(item => {
  const j = item.json;
  const titleText = `${j.job_title} ${j.description} ${j.tags}`;
  const loc = `${j.location_text} ${j.description}`;
  const salary = j.salary || '';

  // Taiwan eligibility score (0-40)
  let taiwanScore = 0;
  if (j.taiwan_eligible === 'yes') {
    if (/worldwide|work from anywhere|global remote|contractor|anywhere/i.test(loc)) taiwanScore = 40;
    else taiwanScore = 30;
  } else if (/apac/i.test(loc)) taiwanScore = 30;
  else if (j.taiwan_eligible === 'unclear') taiwanScore = 20;
  else if (!j.taiwan_eligible) {
    if (/worldwide|work from anywhere|global/i.test(loc)) taiwanScore = 40;
    else taiwanScore = 15;
  } else taiwanScore = 0;

  // Async score (0-25)
  const asyncLevel = j.async_level || 'unknown';
  let asyncScore = 0;
  if (asyncLevel === 'high') asyncScore = 25;
  else if (asyncLevel === 'medium') asyncScore = 20;
  else if (/distributed|remote.?first/i.test(j.description)) asyncScore = 15;
  else asyncScore = 10;

  // Role fit score (0-25)
  let roleScore = 0;
  let roleCategory = 'other';
  if (ROLE_HIGH.some(p => p.test(titleText))) { roleScore = 25; roleCategory = 'high_fit'; }
  else if (ROLE_MEDIUM.some(p => p.test(titleText))) { roleScore = 15; roleCategory = 'adjacent'; }

  // Salary score (0-25)
  let salaryScore = 0;
  const rawNum = parseInt(salary.replace(/[^0-9]/g, ''));
  if (salary && !isNaN(rawNum) && rawNum > 0) {
    // Normalize to monthly (if yearly, divide by 12)
    const monthly = rawNum > 50000 ? Math.round(rawNum / 12) : rawNum;
    if (monthly >= 5000) salaryScore = 25;
    else if (monthly >= 3000) salaryScore = 15;
    else salaryScore = 10;
  }

  const score = taiwanScore + asyncScore + roleScore + salaryScore;

  const whyFit = [
    roleCategory !== 'other' ? `Strong ${roleCategory} role` : '',
    j.taiwan_eligible === 'yes' ? 'Taiwan eligible' : '',
    asyncLevel === 'high' ? 'Async-first culture' : asyncLevel === 'medium' ? 'Flexible hours' : '',
    salaryScore >= 15 ? `Good salary (${salary})` : ''
  ].filter(Boolean).join('. ');

  return {
    json: {
      ...j,
      score,
      role_category: roleCategory,
      why_good_fit: whyFit || 'Matches remote async criteria',
      application_status: 'new',
      notes: ''
    }
  };
});

