const items = $input.all();
return items.map(item => {
  const content = item.json.message?.content ||
    item.json.choices?.[0]?.message?.content ||
    item.json.content || '';
  return {
    json: {
      ...item.json,
      cover_letter_draft: content
    }
  };
});

const allJobs = $input.first().json.all_jobs || [];

const taiwan_tz = { timeZone: 'Asia/Taipei' };
const today = new Date().toLocaleDateString('en-US', { ...taiwan_tz, weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const sorted = [...allJobs].sort((a, b) => (b.score || 0) - (a.score || 0));
const topJobs = sorted.slice(0, 10);
const manualCheck = sorted.filter(j => j.taiwan_eligible === 'unclear' && j.score >= 75);

const rejectedUS = sorted.filter(j => (j._rejected_reason || '').includes('us only') || (j._rejected_reason || '').includes('united states')).length;
const rejectedEU = sorted.filter(j => (j._rejected_reason || '').includes('eu only') || (j._rejected_reason || '').includes('europe')).length;
const rejectedHybrid = sorted.filter(j => (j._rejected_reason || '').includes('hybrid')).length;
const rejectedTZ = sorted.filter(j => j.timezone_risk === 'high').length;

let digest = `DAILY TAIWAN ELIGIBLE ASYNC REMOTE JOBS\n`;
digest += `${today}\n`;
digest += `${'═'.repeat(50)}\n\n`;
digest += `Found ${allJobs.length} eligible jobs today.\n\n`;

digest += `TOP JOBS TODAY\n`;
digest += `${'─'.repeat(50)}\n\n`;

topJobs.forEach((j, i) => {
  digest += `${i + 1}. ${j.job_title}\n`;
  digest += `   Company: ${j.company}\n`;
  digest += `   Score: ${j.score}/100\n`;
  digest += `   Taiwan Eligible: ${j.taiwan_eligible}\n`;
  digest += `   Reason: ${j.taiwan_reason}\n`;
  digest += `   Async Level: ${j.async_level}\n`;
  digest += `   Timezone Risk: ${j.timezone_risk}\n`;
  digest += `   Salary: ${j.salary || 'Not listed'}\n`;
  digest += `   Why it fits Jerry: ${j.why_good_fit}\n`;
  digest += `   Apply: ${j.job_url}\n`;
  if (j.cover_letter_draft) digest += `   [Cover letter draft ready]\n`;
  digest += `\n`;
});

if (manualCheck.length > 0) {
  digest += `\nMANUAL CHECK NEEDED\n`;
  digest += `${'─'.repeat(50)}\n`;
  manualCheck.slice(0, 5).forEach(j => {
    digest += `• ${j.job_title} @ ${j.company} (Score: ${j.score}) - ${j.taiwan_reason}\n`;
    digest += `  ${j.job_url}\n`;
  });
}

digest += `\nREJECTED SUMMARY\n`;
digest += `${'─'.repeat(50)}\n`;
digest += `US-only restrictions: ${rejectedUS}\n`;
digest += `EU-only restrictions: ${rejectedEU}\n`;
digest += `Hybrid/onsite requirements: ${rejectedHybrid}\n`;
digest += `High timezone risk: ${rejectedTZ}\n`;

const htmlDigest = digest
  .replace(/=/g, '=')
  .split('\n')
  .map(line => `<p>${line}</p>`)
  .join('');

return [{
  json: {
    digest_text: digest,
    digest_html: `<html><body style="font-family:monospace;max-width:700px;margin:auto;padding:20px">${htmlDigest}</body></html>`,
    job_count: allJobs.length,
    top_job_count: topJobs.length,
    manual_check_count: manualCheck.length,
    subject: `[Job Hunt] ${topJobs.length} Taiwan-eligible async jobs found - ${today}`
  }
}];
